for x in select * from jsonb_array_elements('[["Barbell Bench Press",["chest"],"compound",["barbell","bench","plates"],"intermediate",4,"5-8",150,["triceps","front delts"],"Barbell_Bench_Press_-_Medium_Grip","The benchmark horizontal press for overall chest size and pressing strength.",["Lie with eyes under the bar, feet flat, shoulder blades pinched and set.","Grip slightly wider than shoulders and unrack over your shoulders.","Lower under control to mid-chest with elbows around 45–70°.","Press up and slightly back to lockout over the shoulders."],["Bouncing the bar off the chest","Flaring elbows to 90°","Lifting the hips off the bench"]],["Incline Barbell Bench Press",["chest"],"compound",["barbell","bench","plates"],"intermediate",4,"6-10",120,["front delts","triceps"],"Barbell_Incline_Bench_Press_-_Medium_Grip","Bench press on a 30–45° incline that shifts emphasis to the upper chest.",["Set the bench to 30–45° and lie with the bar over your eyes.","Unrack with shoulder blades retracted.","Lower to the upper chest just below the collarbone.","Press straight up to lockout."],["Bench set too steep (turns into a shoulder press)","Losing upper-back tightness"]],["Dumbbell Bench Press",["chest"],"compound",["dumbbell","bench"],"beginner",4,"8-12",90,["triceps","front delts"],"Dumbbell_Bench_Press","Flat press with dumbbells for a longer range of motion and balanced left/right strength.",["Sit with dumbbells on your thighs, then kick them up as you lie back.","Start with arms extended, palms forward.","Lower until the dumbbells are level with your chest.","Press up, bringing the dumbbells slightly together."],["Dropping the dumbbells too low and losing shoulder position","Clanking dumbbells at the top"]],["Incline Dumbbell Press",["chest"],"compound",["dumbbell","bench"],"beginner",3,"8-12",90,["front delts","triceps"],"Incline_Dumbbell_Press","Incline dumbbell press targeting the clavicular (upper) chest fibres.",["Set the bench to 30–45°.","Press dumbbells up over the upper chest.","Lower with elbows slightly tucked until a deep stretch.","Press back up without locking hard."],["Arching excessively","Using too steep an angle"]],["Decline Bench Press",["chest"],"compound",["barbell","bench","plates"],"intermediate",3,"6-10",120,["triceps"],"Decline_Barbell_Bench_Press","Bench press on a decline that emphasises the lower chest with less shoulder stress.",["Secure your legs on a decline bench.","Unrack with a spotter or carefully over the chest.","Lower to the lower chest.","Press back to lockout."],["Unracking without a spotter","Bouncing off the sternum"]],["Weighted Dips",["chest","triceps"],"compound",["dip_bars"],"advanced",3,"6-10",120,["front delts"],"Dips_-_Chest_Version","Bodyweight-plus dips leaning forward to load the lower chest and triceps.",["Support yourself on the bars with arms locked, add weight via belt or backpack.","Lean the torso forward slightly.","Lower until shoulders are just below elbows.","Press back up to lockout."],["Going too deep with shoulders rolling forward","Swinging the legs"]],["Push-ups",["chest"],"compound",["bodyweight"],"beginner",3,"10-20",60,["triceps","front delts","core"],"Pushups","The fundamental bodyweight press; scales from knees to weighted.",["Hands slightly wider than shoulders, body in a straight line.","Brace the core and glutes.","Lower until the chest is a fist above the floor.","Push the floor away to full extension."],["Sagging hips","Half reps","Head poking forward"]],["Wide-Grip Push-ups",["chest"],"compound",["bodyweight"],"beginner",3,"10-20",60,["front delts"],"Push-Up_Wide","Push-up variation with a wider hand position for more chest stretch.",["Place hands 1.5× shoulder width.","Keep a rigid plank.","Lower the chest between the hands.","Press back up."],["Hands so wide the range shortens","Flared ribs"]],["Decline Push-ups",["chest"],"compound",["bodyweight","household"],"intermediate",3,"8-15",60,["front delts","triceps"],"Decline_Push-Up","Feet-elevated push-up that shifts load toward the upper chest and shoulders.",["Place feet on a chair or bench, hands on the floor.","Form a straight line from heels to head.","Lower the upper chest toward the floor.","Press back up."],["Piking the hips","Shortening the range"]],["Dumbbell Floor Press",["chest"],"compound",["dumbbell"],"beginner",3,"8-12",90,["triceps"],"Dumbbell_Floor_Press","A home-friendly press with no bench; the floor limits range to protect the shoulders.",["Lie on the floor with knees bent and dumbbells pressed up.","Lower until the upper arms touch the floor.","Pause briefly.","Press back up."],["Bouncing the elbows off the floor"]],["Dumbbell Chest Fly",["chest"],"isolation",["dumbbell","bench"],"beginner",3,"10-15",60,["front delts"],"Dumbbell_Flyes","Wide-arc fly that isolates the chest through a deep stretch.",["Lie flat with dumbbells above the chest, palms facing.","Keep a soft bend in the elbows.","Open the arms in a wide arc until a stretch.","Squeeze back together along the same arc."],["Turning it into a press","Going too heavy and overstretching the shoulder"]],["Cable Chest Fly",["chest"],"isolation",["cable"],"beginner",3,"12-15",60,["front delts"],"Cable_Crossover","Standing cable fly with constant tension through the whole range.",["Set pulleys at shoulder height, stagger your stance.","Arms open with a slight elbow bend.","Bring the handles together in front of the chest.","Return slowly to the stretch."],["Bending the elbows more as you go","Leaning forward too far"]],["Pec Deck Fly",["chest"],"isolation",["machine"],"beginner",3,"12-15",60,[],"Butterfly","Machine fly with a fixed path; easy to push close to failure safely.",["Adjust the seat so the handles are at chest height.","Sit tall with shoulder blades back.","Bring the pads together and squeeze.","Return slowly to a stretch."],["Shoulders rolling forward","Letting the stack crash"]],["Low-to-High Cable Fly",["chest"],"isolation",["cable"],"beginner",3,"12-15",60,["front delts"],"Cable_Crossover","Cable fly from low pulleys upward to target the upper chest.",["Set pulleys at the lowest position.","Start with arms down and slightly back.","Sweep up and in to upper-chest height.","Lower under control."],["Shrugging the shoulders","Using momentum"]],["High-to-Low Cable Fly",["chest"],"isolation",["cable"],"beginner",3,"12-15",60,[],"Cable_Crossover","Cable fly from high pulleys downward to target the lower chest.",["Set pulleys high, step forward.","Arms out with soft elbows.","Sweep down and together toward the hips.","Return to the stretch."],["Pressing instead of sweeping"]],["Resistance Band Fly",["chest"],"isolation",["band"],"beginner",3,"15-20",45,[],"Cross_Over_-_With_Bands","Home alternative to the cable fly using a band anchored behind you.",["Anchor a band behind you at chest height.","Hold an end in each hand with arms open.","Bring the hands together in front.","Return slowly."],["Letting the band snap back"]],["Deadlifts",["back","hamstrings","glutes"],"compound",["barbell","plates"],"advanced",3,"3-6",180,["traps","forearms","core"],"Barbell_Deadlift","Hip hinge lifting the bar from the floor; trains the whole posterior chain.",["Bar over mid-foot, hip-width stance.","Hinge and grip just outside the legs, shins touching the bar.","Brace, flatten the back, pull the slack out of the bar.","Drive the floor away and lock out hips and knees together."],["Rounded lower back","Bar drifting away from the legs","Jerking the bar off the floor"]],["Pull-ups",["back"],"compound",["pullup_bar"],"intermediate",4,"5-10",120,["biceps","rear delts"],"Pullups","Overhand vertical pull; the best bodyweight builder of lat width.",["Hang with an overhand grip slightly wider than shoulders.","Pull the shoulder blades down first.","Drive the elbows down until the chin clears the bar.","Lower to a full hang."],["Kipping","Half reps","Shrugging at the top"]],["Chin-ups",["back","biceps"],"compound",["pullup_bar"],"intermediate",3,"6-10",120,["forearms"],"Chin-Up","Underhand pull-up with more biceps involvement.",["Hang with a shoulder-width underhand grip.","Depress the shoulder blades.","Pull until the chin is over the bar.","Lower to a dead hang."],["Swinging","Not reaching full extension"]],["Barbell Rows",["back"],"compound",["barbell","plates"],"intermediate",4,"6-10",120,["biceps","rear delts"],"Bent_Over_Barbell_Row","Bent-over row for mid-back thickness and pulling strength.",["Hinge to about 45° with a flat back, bar hanging at the knees.","Brace the core.","Row the bar to the lower ribs.","Lower under control."],["Standing up as the set goes on","Jerking with the lower back"]],["T-Bar Rows",["back"],"compound",["barbell","plates"],"intermediate",3,"8-12",90,["biceps","rear delts"],"T-Bar_Row_with_Handle","Landmine-style row allowing heavy loading with a neutral grip.",["Straddle the bar and grip the handle.","Hinge with a neutral spine.","Row the plates to the chest.","Lower to a full stretch."],["Rounding the back","Using leg drive"]],["Single-Arm Dumbbell Rows",["back"],"compound",["dumbbell"],"beginner",3,"8-12",75,["biceps","rear delts"],"One-Arm_Dumbbell_Row","Unilateral row that fixes imbalances and allows a big stretch.",["Brace one hand and knee on a bench or chair.","Let the dumbbell hang under the shoulder.","Row toward the hip, elbow close.","Lower to a full stretch."],["Twisting the torso","Shrugging the weight up"]],["Lat Pulldowns",["back"],"compound",["cable"],"beginner",3,"8-12",90,["biceps"],"Wide-Grip_Lat_Pulldown","Machine vertical pull; scalable alternative to pull-ups.",["Grip the bar slightly wider than shoulders, thighs under the pads.","Lean back slightly.","Pull the bar to the upper chest.","Return until arms are straight."],["Pulling behind the neck","Leaning way back to use momentum"]],["Seated Cable Rows",["back"],"compound",["cable"],"beginner",3,"10-12",90,["biceps","rear delts"],"Seated_Cable_Rows","Horizontal cable row for mid-back and lat development.",["Sit with knees soft, chest tall.","Reach forward to a stretch.","Row the handle to the stomach, squeezing the shoulder blades.","Return under control."],["Rocking the torso","Rounding forward at the stretch"]],["Inverted Rows",["back"],"compound",["household"],"beginner",3,"8-15",75,["biceps","rear delts"],"Inverted_Row","Horizontal bodyweight row under a sturdy table or bar.",["Lie under a sturdy table or low bar and grip the edge.","Keep the body straight, heels on the floor.","Pull the chest to the edge.","Lower to straight arms."],["Sagging hips","Using an unstable table"]],["Band Lat Pulldown",["back"],"compound",["band"],"beginner",3,"12-20",60,["biceps"],"Band_Assisted_Pull-Up","Home lat pulldown using a band anchored overhead.",["Anchor a band high (door anchor).","Kneel and grip the band with arms overhead.","Pull elbows down to the ribs.","Return slowly."],["Pulling with the arms only"]],["Straight-Arm Cable Pulldowns",["back"],"isolation",["cable"],"beginner",3,"12-15",60,[],"Straight-Arm_Pulldown","Lat isolation with straight arms, removing the biceps.",["Face a high pulley holding a bar with straight arms.","Hinge slightly at the hips.","Sweep the bar down to the thighs.","Return to overhead."],["Bending the elbows","Using the torso"]],["Dumbbell Pullovers",["back"],"isolation",["dumbbell","bench"],"intermediate",3,"10-12",60,["chest","triceps"],"Straight-Arm_Dumbbell_Pullover","Overhead arc that stretches and loads the lats.",["Lie across or along a bench holding one dumbbell over the chest.","Keep elbows slightly bent.","Lower the dumbbell behind the head.","Pull back over the chest."],["Bending the elbows into a triceps extension"]],["Cable Pullovers",["back"],"isolation",["cable"],"beginner",3,"12-15",60,[],"Rope_Straight-Arm_Pulldown","Rope pullover from a high pulley for constant lat tension.",["Attach a rope to a high pulley.","Hinge forward with arms overhead.","Pull the rope to the hips, flaring the ends.","Return slowly."],["Shrugging the shoulders up"]],["Reverse Cable Pullovers",["back"],"isolation",["cable","bench"],"intermediate",3,"12-15",60,[],"Wide-Grip_Decline_Barbell_Pullover","Lying pullover against a low cable for tension in the stretched position.",["Lie on a bench with your head toward a low pulley.","Hold the bar over the chest.","Let it travel back overhead to a stretch.","Pull back over the chest."],["Losing control at the stretch"]],["Barbell Squats",["quads","glutes"],"compound",["barbell","rack","plates"],"intermediate",4,"5-8",180,["hamstrings","core"],"Barbell_Squat","The primary lower-body strength lift.",["Bar on upper traps, feet shoulder-width, toes slightly out.","Brace and break at hips and knees together.","Descend until thighs are at least parallel.","Drive up keeping the chest proud."],["Knees caving in","Heels lifting","Good-morning out of the hole"]],["Front Squats",["quads"],"compound",["barbell","rack","plates"],"advanced",4,"5-8",150,["glutes","core"],"Front_Barbell_Squat","Bar in the front rack; upright torso, heavy quad emphasis.",["Rack the bar on the front delts, elbows high.","Brace hard.","Squat straight down, staying upright.","Drive up leading with the elbows."],["Elbows dropping","Rounding the upper back"]],["Hack Squats",["quads"],"compound",["machine"],"beginner",3,"8-12",120,["glutes"],"Hack_Squat","Machine squat with back support that isolates the quads safely.",["Shoulders under the pads, feet mid-platform.","Release the safeties.","Lower deep under control.","Press to just short of lockout."],["Feet too high (shifts to glutes)","Locking knees hard"]],["Leg Press",["quads","glutes"],"compound",["machine"],"beginner",3,"10-15",120,["hamstrings"],"Leg_Press","Heavy machine press for quad and glute volume without spinal loading.",["Sit with feet shoulder-width on the platform.","Release the sled.","Lower until knees reach about 90°, lower back flat.","Press back up."],["Lower back rounding off the pad","Locking the knees"]],["Bulgarian Split Squats",["quads","glutes"],"compound",["dumbbell","bench"],"intermediate",3,"8-12",90,["hamstrings"],"Split_Squat_with_Dumbbells","Rear-foot-elevated split squat; brutal unilateral leg builder.",["Rear foot on a bench or chair, front foot forward.","Hold dumbbells at your sides (or none).","Lower until the rear knee nearly touches the floor.","Drive through the front heel."],["Front foot too close","Torso collapsing forward"]],["Goblet Squats",["quads","glutes"],"compound",["dumbbell"],"beginner",3,"10-15",75,["core"],"Goblet_Squat","Squat holding one dumbbell or kettlebell at the chest; ideal at home.",["Hold a dumbbell vertically at your chest.","Feet shoulder-width.","Sit down between your heels, elbows inside knees.","Stand back up."],["Heels lifting","Rounding the back"]],["Bodyweight Squats",["quads","glutes"],"compound",["bodyweight"],"beginner",3,"15-25",45,["hamstrings"],"Bodyweight_Squat","No-equipment squat for beginners and high-rep conditioning.",["Feet shoulder-width, arms forward.","Sit back and down.","Reach parallel or below.","Stand tall."],["Knees caving","Partial depth"]],["Leg Extensions",["quads"],"isolation",["machine"],"beginner",3,"12-15",60,[],"Leg_Extensions","Machine isolation for the quadriceps, especially the rectus femoris.",["Pad on the lower shins, knees aligned with the pivot.","Extend the legs fully.","Squeeze for a second.","Lower under control."],["Swinging the weight","Lifting the hips"]],["Romanian Deadlifts",["hamstrings","glutes"],"compound",["barbell","plates"],"intermediate",3,"8-10",120,["lower back"],"Romanian_Deadlift","Hip hinge from the top that loads the hamstrings in a long stretch.",["Stand holding the bar at hip height.","Soften the knees and push the hips back.","Slide the bar down the thighs until a strong hamstring stretch.","Drive the hips forward to stand."],["Rounding the back","Bending the knees too much (becomes a squat)"]],["Dumbbell Romanian Deadlifts",["hamstrings","glutes"],"compound",["dumbbell"],"beginner",3,"10-12",90,["lower back"],"Stiff-Legged_Dumbbell_Deadlift","Dumbbell version of the RDL for home training.",["Hold dumbbells in front of the thighs.","Push hips back with soft knees.","Lower to mid-shin with a flat back.","Stand by squeezing the glutes."],["Letting the dumbbells drift forward"]],["Stiff-Leg Deadlifts",["hamstrings"],"compound",["barbell","plates"],"intermediate",3,"8-10",120,["glutes","lower back"],"Stiff-Legged_Barbell_Deadlift","Near-straight-leg deadlift with maximal hamstring stretch.",["Stand with the bar, knees almost locked.","Hinge forward, keeping the bar close.","Lower as far as flexibility allows with a flat back.","Return to standing."],["Rounding the lower back to gain range"]],["Lying Leg Curls",["hamstrings"],"isolation",["machine"],"beginner",3,"10-15",60,["calves"],"Lying_Leg_Curls","Prone machine curl isolating the hamstrings.",["Lie face down, pad just above the heels.","Curl the heels toward the glutes.","Squeeze at the top.","Lower slowly."],["Hips lifting off the pad"]],["Seated Leg Curls",["hamstrings"],"isolation",["machine"],"beginner",3,"10-15",60,[],"Seated_Leg_Curl","Seated machine curl; trains hamstrings at a longer muscle length.",["Sit with the pad above the heels, thigh pad locked down.","Curl down and back.","Pause.","Return slowly."],["Leaning back to cheat"]],["Nordic Hamstring Curls",["hamstrings"],"isolation",["bodyweight","household"],"advanced",3,"4-8",120,[],"Natural_Glute_Ham_Raise","Eccentric-focused bodyweight curl; excellent for hamstring resilience.",["Kneel with ankles anchored under a couch or partner.","Keep hips extended.","Lower the torso forward as slowly as possible.","Catch with your hands and push back up."],["Bending at the hips","Dropping fast"]],["Band Leg Curls",["hamstrings"],"isolation",["band"],"beginner",3,"15-20",45,[],"Seated_Band_Hamstring_Curl","Band-resisted leg curl for home training.",["Anchor a band low and loop it around the ankle.","Lie face down or sit facing the anchor.","Curl the heel toward the glute.","Return slowly."],["Letting the band yank the leg back"]],["Hip Thrusts",["glutes"],"compound",["barbell","bench","plates"],"intermediate",4,"8-12",90,["hamstrings"],"Barbell_Hip_Thrust","Top glute builder; peak tension at full hip extension.",["Upper back on a bench, bar padded over the hips.","Feet flat, shins vertical at the top.","Drive the hips up to full extension.","Lower under control."],["Overarching the lower back","Feet too far forward"]],["Glute Bridges",["glutes"],"compound",["bodyweight"],"beginner",3,"12-20",45,["hamstrings"],"Butt_Lift_Bridge","Floor hip extension; add a dumbbell or band to progress.",["Lie on your back, knees bent, feet flat.","Brace and drive through the heels.","Lift the hips to a straight line.","Squeeze, then lower."],["Pushing through the toes","Arching the back"]],["Walking Lunges",["glutes","quads"],"compound",["dumbbell"],"intermediate",3,"10-12",90,["hamstrings"],"Dumbbell_Lunges","Travelling lunges for glutes, quads and balance.",["Hold dumbbells at your sides.","Step forward into a lunge.","Lower until the back knee nearly touches.","Drive through the front foot into the next step."],["Short steps that load the knee","Leaning sideways"]],["Reverse Lunges",["glutes","quads"],"compound",["bodyweight"],"beginner",3,"10-12",75,["hamstrings"],"Dumbbell_Rear_Lunge","Step-back lunge that is kinder to the knees.",["Stand tall.","Step one foot back.","Lower until both knees are about 90°.","Push back to the start."],["Front knee caving inward"]],["Cable Kickbacks",["glutes"],"isolation",["cable"],"beginner",3,"12-15",45,[],"One-Legged_Cable_Kickback","Cable isolation for glute max.",["Attach an ankle cuff to a low pulley.","Hinge slightly, holding the frame.","Kick the leg back and up.","Return slowly."],["Arching the lower back to get height"]],["Band Kickbacks",["glutes"],"isolation",["band"],"beginner",3,"15-20",45,[],"Glute_Kickback","Band-resisted kickback for home glute work.",["Loop a band around both feet on all fours.","Kick one leg back.","Squeeze the glute.","Return."],["Rotating the hips"]],["Standing Calf Raises",["calves"],"isolation",["machine"],"beginner",4,"10-15",60,[],"Standing_Calf_Raises","Straight-knee calf raise loading the gastrocnemius.",["Shoulders under the pads, balls of the feet on the edge.","Lower to a deep stretch.","Rise as high as possible.","Pause at the top."],["Bouncing","Bending the knees"]],["Seated Calf Raises",["calves"],"isolation",["machine"],"beginner",3,"12-20",60,[],"Seated_Calf_Raise","Bent-knee calf raise targeting the soleus.",["Sit with pads on the lower thighs.","Lower the heels fully.","Press up onto the toes.","Pause and lower."],["Short range of motion"]],["Donkey Calf Raises",["calves"],"isolation",["machine"],"intermediate",3,"12-15",60,[],"Donkey_Calf_Raises","Hinged-over calf raise for a deep gastrocnemius stretch.",["Hinge forward with hips under the pad.","Balls of the feet on the block.","Lower to a stretch.","Rise fully."],["Bending the knees"]],["Single-Leg Calf Raises",["calves"],"isolation",["bodyweight"],"beginner",3,"12-20",45,[],"Dumbbell_Seated_One-Leg_Calf_Raise","Unilateral calf raise on a step; perfect at home.",["Stand on one foot on a step, holding support.","Lower the heel below the step.","Rise to the top.","Pause, then lower."],["Rushing reps"]],["Barbell Overhead Press",["shoulders"],"compound",["barbell","plates","rack"],"intermediate",4,"5-8",150,["triceps","upper chest"],"Standing_Military_Press","Standing strict press; the main overhead strength lift.",["Bar on front delts, grip just outside shoulders.","Squeeze glutes and brace.","Press up, moving the head back then through.","Lock out overhead."],["Leaning back excessively","Pressing forward rather than up"]],["Dumbbell Shoulder Press",["shoulders"],"compound",["dumbbell"],"beginner",3,"8-12",90,["triceps"],"Dumbbell_Shoulder_Press","Seated or standing dumbbell press for shoulder size.",["Dumbbells at shoulder height, palms forward.","Brace the core.","Press up until arms are straight.","Lower to ear level."],["Arching the lower back","Partial range"]],["Arnold Press",["shoulders"],"compound",["dumbbell"],"intermediate",3,"8-12",90,["triceps"],"Arnold_Dumbbell_Press","Rotating dumbbell press that hits front and side delts.",["Start with dumbbells at the chin, palms facing you.","Rotate the palms out as you press.","Finish palms forward overhead.","Reverse on the way down."],["Rushing the rotation"]],["Push Press",["shoulders"],"compound",["barbell","plates","rack"],"advanced",4,"3-6",150,["triceps","quads"],"Push_Press","Overhead press with leg drive for power and heavier loads.",["Bar in the front rack.","Dip a few inches at the knees.","Drive explosively and press.","Lock out overhead."],["Dipping too deep","Pressing before the drive"]],["Pike Push-ups",["shoulders"],"compound",["bodyweight"],"intermediate",3,"6-12",75,["triceps"],"Handstand_Push-Ups","Bodyweight overhead press with hips high.",["Start in a push-up position, walk the feet in so hips are high.","Lower the head toward the floor in front of the hands.","Press back up.","Elevate the feet to progress."],["Lowering the chest instead of the head"]],["Dumbbell Lateral Raises",["shoulders"],"isolation",["dumbbell"],"beginner",4,"12-20",45,[],"Side_Lateral_Raise","Side delt isolation for shoulder width.",["Stand with dumbbells at your sides.","Raise out to the sides with soft elbows.","Stop at shoulder height.","Lower slowly."],["Swinging","Shrugging the traps"]],["Cable Lateral Raises",["shoulders"],"isolation",["cable"],"beginner",3,"12-15",45,[],"Cable_Seated_Lateral_Raise","Single-arm cable raise with tension at the bottom.",["Stand side-on to a low pulley.","Hold the handle across the body.","Raise out to shoulder height.","Lower slowly."],["Leaning away too far"]],["Band Lateral Raises",["shoulders"],"isolation",["band"],"beginner",3,"15-20",45,[],"Lateral_Raise_-_With_Bands","Lateral raise with a band under the feet.",["Stand on the band, ends in hands.","Raise to