Squat-thrust-jump combination for high-intensity work.",["Squat and place hands down.","Jump feet back to a plank.","Jump feet in.","Explode up."],["Sagging plank"]],["High Knees",["cardio"],"cardio",["bodyweight"],"beginner",4,"30-45s",30,["hip flexors"],"Fast_Skipping","Running in place with high knee drive.",["Run on the spot.","Drive knees to hip height.","Pump the arms.","Stay on the balls of the feet."],["Leaning back"]],["Jumping Jacks",["cardio"],"cardio",["bodyweight"],"beginner",3,"45-60s",30,[],"Star_Jump","Simple warm-up and conditioning drill.",["Jump feet out while raising arms.","Jump back in.","Keep a steady rhythm.","Land softly."],["Landing heavily"]],["Sprint Intervals",["cardio"],"cardio",["bodyweight"],"advanced",8,"15-30s",90,["legs"],"Wind_Sprints","Short all-out sprints with full recovery.",["Warm up thoroughly.","Sprint all-out for 15–30 s.","Walk to recover.","Repeat."],["Skipping the warm-up"]],["HIIT Training",["cardio"],"cardio",["bodyweight"],"intermediate",8,"30s on/30s off",30,[],"Mountain_Climbers","Alternating hard and easy intervals for time-efficient conditioning.",["Pick 3–5 movements.","Work hard for the interval.","Rest for the interval.","Repeat the circuit."],["Intervals not hard enough"]],["LISS Cardio",["cardio"],"cardio",["bodyweight"],"beginner",1,"30-60min",0,[],"Trail_Running_Walking","Low-intensity steady-state work at conversational pace.",["Choose walking, cycling or rowing.","Keep heart rate ~60–70% max.","Stay steady.","Track duration."],["Drifting into high intensity"]]]'::jsonb) loop
 insert into public.exercises (slug, name, classification, difficulty, description, instructions, common_mistakes,
   secondary_muscles, rec_sets, rec_reps, rest_seconds, environments, image_id)
 values (trim(both '-' from regexp_replace(lower(x->>0), '[^a-z0-9]+', '-', 'g')), x->>0, x->>2, x->>4, x->>10,
   array(select jsonb_array_elements_text(x->11)), array(select jsonb_array_elements_text(x->12)),
   array(select jsonb_array_elements_text(x->8)), (x->>5)::int, x->>6, (x->>7)::int,
   case when array(select jsonb_array_elements_text(x->3)) <@ home then array['home','gym'] else array['gym'] end,
   x->>9)
 returning id into eid;
 insert into public.exercise_muscles select eid, g from jsonb_array_elements_text(x->1) g;
 insert into public.exercise_equipment select eid, g from jsonb_array_elements_text(x->3) g;
end loop; end $$;
